(2415822, 333981, 37252, '<td valign="top">the color tones look a bit muddy or muted here, giving this image a flat appearance.</td>', 'the color tones look a bit muddy or muted here, giving this image a flat appearance.', '2006-05-15 01:14:11.000000', NULL, 1),
(2415825, 334297, 42826, '<td valign="top">that''s a very intersting shot...love the motion in the hands...the love blues too!!</td>', 'that''s a very intersting shot...love the motion in the hands...the love blues too!!', '2006-05-15 01:14:39.000000', NULL, 1),
(2415830, 333620, 37252, '<td valign="top">This is actually a candid not a portriat. A potrait indicates the subject should be posed - in this challenge the posing would be done in his/her environment. If this man''s environment is a golf course, then perhaps you could have had him pose with his clubs, or along side the flag.</td>', 'This is actually a candid not a portriat. A potrait indicates the subject should be posed - in this challenge the posing would be done in his/her environment. If this man''s environment is a golf course, then perhaps you could have had him pose with his clubs, or along side the flag.', '2006-05-15 01:15:57.000000', NULL, 1),
(2415836, 334449, 37252, '<td valign="top">I like the image overall, and feel it meets the challenge. I would have liked to see the colors brought out more in the trees of the background, and the spot along the right cloned out.</td>', 'I like the image overall, and feel it meets the challenge. I would have liked to see the colors brought out more in the trees of the background, and the spot along the right cloned out.', '2006-05-15 01:17:15.000000', NULL, 1),
