(2416664, 332250, 37719, '<td valign="top">Very nice portrait.  The exposure is perfect for the environment aspect of this shot.  The motion of the kids really emphasizes the subject very nicely.  Well done! 10</td>', 'Very nice portrait.  The exposure is perfect for the environment aspect of this shot.  The motion of the kids really emphasizes the subject very nicely.  Well done! 10', '2006-05-15 08:47:25.000000', NULL, 1),
(2416666, 333872, 38032, '<td valign="top">This is the first one today that struck me as EXACTLY metting the challenge.  A guy at work - stopping for a portrait in front of his ship or whatever.  Great allaround  -the only thing that I would change would be the pose-  the hands seem to be awkward.   Brilliant.  8</td>', 'This is the first one today that struck me as EXACTLY metting the challenge.  A guy at work - stopping for a portrait in front of his ship or whatever.  Great allaround  -the only thing that I would change would be the pose-  the hands seem to be awkward.   Brilliant.  8', '2006-05-15 08:47:40.000000', NULL, 1),
(2416668, 334590, 48228, '<td valign="top">I really think the black and white tones really help give this image it''s country feel to this enviromental image.....Very well done.....</td>', 'I really think the black and white tones really help give this image it''s country feel to this enviromental image.....Very well done.....', '2006-05-15 08:48:10.000000', NULL, 1),
