(2417226, 334125, 51538, '<td valign="top">Nice conceptual photo - but the portrait component is diminished because the face of the painter is not visible.</td>', 'Nice conceptual photo - but the portrait component is diminished because the face of the painter is not visible.', '2006-05-15 12:10:54.000000', NULL, 1),
(2417231, 334102, 51538, '<td valign="top">Having children myself, I awlays tend to find photos of children in their many embarassing situations somewhat sad.  I seem to think the photographer is taking advantage of the situation and is getting something from exposing another''s vulnerabilities.  My 0.02c.</td>', 'Having children myself, I awlays tend to find photos of children in their many embarassing situations somewhat sad.  I seem to think the photographer is taking advantage of the situation and is getting something from exposing another''s vulnerabilities.  My 0.02c.', '2006-05-15 12:12:31.000000', NULL, 1),
(2417233, 334545, 70, '<td valign="top">Really cute! I''m not a fan of the pinkish sepia processing here but the setup is great.</td>', 'Really cute! I''m not a fan of the pinkish sepia processing here but the setup is great.', '2006-05-15 12:12:49.000000', NULL, 1),
(2417236, 333595, 51538, '<td valign="top">Violin is diminished by being at this angle.  A little more side-on would have been better in my opinion.</td>', 'Violin is diminished by being at this angle.  A little more side-on would have been better in my opinion.', '2006-05-15 12:13:08.000000', NULL, 1),
(2417238, 334230, 51538, '<td valign="top">I''d like more of the person in the frame.</td>', 'I''d like more of the person in the frame.', '2006-05-15 12:13:37.000000', NULL, 1),
(2417239, 334149, 70, '<td valign="top">Nice portrait. The b&amp;w conversion seems a little flat.</td>', 'Nice portrait. The b&w conversion seems a little flat.', '2006-05-15 12:13:39.000000', NULL, 1),
(2417240, 334578, 51538, '<td valign="top">Nice moment caught.</td>', 'Nice moment caught.', '2006-05-15 12:13:57.000000', NULL, 1),
(2417241, 333889, 30049, '<td valign="top">This is a nice shot.  At first glance from the thumbnail I couldn''t figure it out because the mans hair blends into the background.  At full size I still enjoy the image although it still would be nice to have something less distracting behind his head.  JMO of course.  You should do well with this.  Good luck in the challenge.</td>', 'This is a nice shot.  At first glance from the thumbnail I couldn''t figure it out because the mans hair blends into the background.  At full size I still enjoy the image although it still would be nice to have something less distracting behind his head.  JMO of course.  You should do well with this.  Good luck in the challenge.', '2006-05-15 12:13:59.000000', NULL, 1),
(2417242, 334589, 32644, '<td valign="top">This is a fun shot. <br/>His/her face in the mirror would have made it perfect.</td>', 'This is a fun shot. His/her face in the mirror would have made it perfect.', '2006-05-15 12:14:13.000000', NULL, 1),
