(2417275, 334526, 70, '<td valign="top">Very nice portrait. The yellow in the background is a bit distracting, I''d probably try to remove that so that it doesn''t draw the eye away from the subject.</td>', 'Very nice portrait. The yellow in the background is a bit distracting, I''d probably try to remove that so that it doesn''t draw the eye away from the subject.', '2006-05-15 12:21:01.000000', NULL, 1),
(2417279, 334090, 51538, '<td valign="top">Nice colour and pleasing chrome.</td>', 'Nice colour and pleasing chrome.', '2006-05-15 12:22:26.000000', NULL, 1),
(2417282, 333531, 15711, '<td valign="top">Where is the portrait? I''d love it in another challenge, but it has nothing to do with environmental portrait. I mean, if you define it as the diminishing environment, sure, but that wasn''t the directive.  The negative space, contrast and filter is great, just not for this challenge.</td>', 'Where is the portrait? I''d love it in another challenge, but it has nothing to do with environmental portrait. I mean, if you define it as the diminishing environment, sure, but that wasn''t the directive.  The negative space, contrast and filter is great, just not for this challenge.', '2006-05-15 12:23:54.000000', NULL, 1),
(2417284, 334504, 51538, '<td valign="top">The intricacies of a nice (dust-free) piano interior and a human face full of character seem to make for a very pleasing portrait.  Ligthing this scene was a skillful job.</td>', 'The intricacies of a nice (dust-free) piano interior and a human face full of character seem to make for a very pleasing portrait.  Ligthing this scene was a skillful job.', '2006-05-15 12:25:06.000000', NULL, 1),
(2417293, 334316, 51538, '<td valign="top">Nice DOF.  I notice many of the nouveau riche in my area are buying cats and dogs.  Perhaps if they also acquire raptors we will have some sort of envionmental equilibrium developing too. ;-)</td>', 'Nice DOF.  I notice many of the nouveau riche in my area are buying cats and dogs.  Perhaps if they also acquire raptors we will have some sort of envionmental equilibrium developing too. ;-)', '2006-05-15 12:26:42.000000', NULL, 1),
(2417296, 333367, 51538, '<td valign="top">Interesting processing - it has a painterly feel to it.  The outline of the figure is especially clear.</td>', 'Interesting processing - it has a painterly feel to it.  The outline of the figure is especially clear.', '2006-05-15 12:27:49.000000', NULL, 1),
(2417302, 331849, 54731, '<td valign="top">Portrait of a flower??? Nice though...</td>', 'Portrait of a flower??? Nice though...', '2006-05-15 12:29:23.000000', NULL, 1),
(2417304, 333373, 51538, '<td valign="top">I like the feeling expression - the communication between photographer and subject is calm and pleasant making the image nice to look at.</td>', 'I like the feeling expression - the communication between photographer and subject is calm and pleasant making the image nice to look at.', '2006-05-15 12:29:44.000000', NULL, 1),
(2417312, 334375, 15711, '<td valign="top">She reminds me of a young Linda Hamilton.  Lovely girl.  I consider this more of a candid than a portrait. Hard line though - maybe she was posing for you. Nice post editing - or maybe that''s the stage lighting.</td>', 'She reminds me of a young Linda Hamilton.  Lovely girl.  I consider this more of a candid than a portrait. Hard line though - maybe she was posing for you. Nice post editing - or maybe that''s the stage lighting.', '2006-05-15 12:30:52.000000', NULL, 1),
(2417319, 333948, 51538, '<td valign="top">Nice photo - plenty of interest.  The title is a bit obscure though.</td>', 'Nice photo - plenty of interest.  The title is a bit obscure though.', '2006-05-15 12:33:15.000000', NULL, 1),
(2417320, 333922, 51538, '<td valign="top">Lovely focus and colour.</td>', 'Lovely focus and colour.', '2006-05-15 12:33:27.000000', NULL, 1),
