(2417350, 332223, 51538, '<td valign="top">Narcissus ;-)  But well shot.</td>', 'Narcissus ;-)  But well shot.', '2006-05-15 12:41:59.000000', NULL, 1),
(2417354, 334408, 51538, '<td valign="top">That''s a beauty of a spontaneous shot.</td>', 'That''s a beauty of a spontaneous shot.', '2006-05-15 12:43:09.000000', NULL, 1),
