(2417415, 332450, 36371, '<td valign="top">Was this taken on St. Croix?</td>', 'Was this taken on St. Croix?', '2006-05-15 13:01:06.000000', NULL, 1),
(2417449, 334176, 48545, '<td valign="top">Well he is definately in his environment!  There are a few blown out white patches that are a little distracting.  The out of focus leaves at the front add to the image I think (makes the viewer think your tracking it!)   Colours are nice, just wish we could see more of the face</td>', 'Well he is definately in his environment!  There are a few blown out white patches that are a little distracting.  The out of focus leaves at the front add to the image I think (makes the viewer think your tracking it!)   Colours are nice, just wish we could see more of the face', '2006-05-15 13:17:12.000000', NULL, 1),
(2417459, 332949, 48545, '<td valign="top">Outrageous border! they don''t usually do too well on DPC, nor images of peoples trinkets!  good luck though, the photo made me giggle so it must have something to it.  Main critism is that the focus seems a tad soft</td>', 'Outrageous border! they don''t usually do too well on DPC, nor images of peoples trinkets!  good luck though, the photo made me giggle so it must have something to it.  Main critism is that the focus seems a tad soft', '2006-05-15 13:19:14.000000', NULL, 1),
(2417463, 333259, 48545, '<td valign="top">Seems to be exposed for the sky which is great and nice and blue, but I really want to see the expression on the childs face.  If this was possible I think it would be quite a powerful image as the angle of the camera adds to the fun the child is having</td>', 'Seems to be exposed for the sky which is great and nice and blue, but I really want to see the expression on the childs face.  If this was possible I think it would be quite a powerful image as the angle of the camera adds to the fun the child is having', '2006-05-15 13:20:35.000000', NULL, 1),
(2417473, 333655, 70, '<td valign="top">I''m guessing you meant prey. Either way, I have a hard time considering this a portrait.</td>', 'I''m guessing you meant prey. Either way, I have a hard time considering this a portrait.', '2006-05-15 13:23:57.000000', NULL, 1),
