(2418651, 334488, 33352, '<td valign="top">Wel taken for this challenge,the stop action is great....9</td>', 'Wel taken for this challenge,the stop action is great....9', '2006-05-15 20:07:07.000000', NULL, 1),
(2418653, 334590, 33352, '<td valign="top">Just as the details say A cowboy and his horse,really like the B&amp;W tone on this image,suites challenge well.....</td>', 'Just as the details say A cowboy and his horse,really like the B&W tone on this image,suites challenge well.....', '2006-05-15 20:08:33.000000', NULL, 1),
(2418672, 332250, 24642, '<td valign="top">Bright, colorful and tells a story.</td>', 'Bright, colorful and tells a story.', '2006-05-15 20:18:58.000000', NULL, 1),
(2418714, 333801, 41200, '<td valign="top">Nicely done! Easily a ribbon winner. Congrats on a great shot.</td>', 'Nicely done! Easily a ribbon winner. Congrats on a great shot.', '2006-05-15 20:40:01.000000', NULL, 1),
(2418715, 333866, 42984, '<td valign="top">Really interesting image, nice environmental context.  i doubt whether women were allowed to do that work way back then but it doesn''t matter for the pic.  If you were looking for ways to grow its score, perhapds the bright light on the forge base is distracting from the main strength of the image.  I was thinking about how to take that away and figured that you could use an upside-down graduated mask for the bottom half of the pic.  Depending on the opacity of it, you could then really force the eye into the main part of the image and I think it would look seriously powerful</td>', 'Really interesting image, nice environmental context.  i doubt whether women were allowed to do that work way back then but it doesn''t matter for the pic.  If you were looking for ways to grow its score, perhapds the bright light on the forge base is distracting from the main strength of the image.  I was thinking about how to take that away and figured that you could use an upside-down graduated mask for the bottom half of the pic.  Depending on the opacity of it, you could then really force the eye into the main part of the image and I think it would look seriously powerful', '2006-05-15 20:40:45.000000', NULL, 1),
(2418724, 334165, 41200, '<td valign="top">Haaa...nice take on the challenge!</td>', 'Haaa...nice take on the challenge!', '2006-05-15 20:43:06.000000', NULL, 1),
(2418754, 332223, 41200, '<td valign="top">Congratulations on a nice image. Well thought out.</td>', 'Congratulations on a nice image. Well thought out.', '2006-05-15 20:56:00.000000', NULL, 1),
(2418774, 332280, 36006, '<td valign="top">Excellent job, great imagination.</td>', 'Excellent job, great imagination.', '2006-05-15 21:04:14.000000', NULL, 1),
(2418776, 333647, 36006, '<td valign="top">Nice lighting. Great job, good imagination.</td>', 'Nice lighting. Great job, good imagination.', '2006-05-15 21:04:43.000000', NULL, 1),
(2418804, 333647, 37779, '<td valign="top">Dude, this is all sorts of WOW.</td>', 'Dude, this is all sorts of WOW.', '2006-05-15 21:19:21.000000', NULL, 1),
(2418809, 332223, 37779, '<td valign="top">10. Ribbon. Amazing.</td>', '10. Ribbon. Amazing.', '2006-05-15 21:20:30.000000', NULL, 1),
(2418820, 334475, 55642, '<td valign="top">I don''t get "boxer" from this. Maybe bartender or bar patron.</td>', 'I don''t get "boxer" from this. Maybe bartender or bar patron.', '2006-05-15 21:24:08.000000', NULL, 1),
(2418825, 334449, 55642, '<td valign="top">The light is a bit harsh here, which does these lovely birds no justice. There''s a dust spot in the upper left quadrant.</td>', 'The light is a bit harsh here, which does these lovely birds no justice. There''s a dust spot in the upper left quadrant.', '2006-05-15 21:25:26.000000', NULL, 1),
(2418828, 334214, 55642, '<td valign="top">Nice colors, though there are some blown highlights on the girl''s arm and shoulder.</td>', 'Nice colors, though there are some blown highlights on the girl''s arm and shoulder.', '2006-05-15 21:26:16.000000', NULL, 1),
(2418834, 334567, 51125, '<td valign="top">Nice light and warm smile.   A narrower DOF would have helped.</td>', 'Nice light and warm smile.   A narrower DOF would have helped.', '2006-05-15 21:28:07.000000', NULL, 1),
(2418846, 334338, 51125, '<td valign="top">Strong sense of moment.  On my screen the skin tone is off (there is an off putting subtle but notiveable green tinge).</td>', 'Strong sense of moment.  On my screen the skin tone is off (there is an off putting subtle but notiveable green tinge).', '2006-05-15 21:32:04.000000', NULL, 1),
(2418851, 334359, 51125, '<td valign="top">There is a focus problem here and hte fence is hurting you.</td>', 'There is a focus problem here and hte fence is hurting you.', '2006-05-15 21:33:56.000000', NULL, 1),
(2418854, 334399, 51125, '<td valign="top">Great light and wonderful setting.  The melodrama is overdone but I assume that is intentional.</td>', 'Great light and wonderful setting.  The melodrama is overdone but I assume that is intentional.', '2006-05-15 21:35:09.000000', NULL, 1),
(2418857, 333755, 51125, '<td valign="top">I would have loved to see an even lower perspective to get teh building out of the shot.</td>', 'I would have loved to see an even lower perspective to get teh building out of the shot.', '2006-05-15 21:36:03.000000', NULL, 1),
(2418864, 334568, 51125, '<td valign="top">Nice light and great smile but not enough of the environment for this challenge.</td>', 'Nice light and great smile but not enough of the environment for this challenge.', '2006-05-15 21:39:13.000000', NULL, 1),
(2418867, 334420, 51125, '<td valign="top">Great tonal range and composition.</td>', 'Great tonal range and composition.', '2006-05-15 21:39:48.000000', NULL, 1),
(2418871, 333502, 51125, '<td valign="top">Great processing, the flash actually works here, and the skewed frame adds effective tension.</td>', 'Great processing, the flash actually works here, and the skewed frame adds effective tension.', '2006-05-15 21:41:20.000000', NULL, 1),
(2418875, 333821, 51125, '<td valign="top">Great look and light but I would like to see more environment (fire truck/house/people) to add context.</td>', 'Great look and light but I would like to see more environment (fire truck/house/people) to add context.', '2006-05-15 21:42:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2418886, 332250, 51125, '<td valign="top">Outstanding light and original idea!</td>', 'Outstanding light and original idea!', '2006-05-15 21:49:47.000000', NULL, 1),
(2418887, 334524, 51125, '<td valign="top">Great except focus.</td>', 'Great except focus.', '2006-05-15 21:50:11.000000', NULL, 1),
(2418889, 334573, 51125, '<td valign="top">I would love to see a plate or more of the ballfield for an environmental portrait.</td>', 'I would love to see a plate or more of the ballfield for an environmental portrait.', '2006-05-15 21:51:17.000000', NULL, 1),
(2418891, 334241, 51125, '<td valign="top">Outstanding light and DOF.</td>', 'Outstanding light and DOF.', '2006-05-15 21:52:07.000000', NULL, 1),
(2418895, 333367, 51125, '<td valign="top">Great processing and sense of moment.  The perspective works very well.</td>', 'Great processing and sense of moment.  The perspective works very well.', '2006-05-15 21:52:42.000000', NULL, 1),
(2418899, 333757, 51125, '<td valign="top">wonderful light.</td>', 'wonderful light.', '2006-05-15 21:53:23.000000', NULL, 1),
(2418901, 333447, 51125, '<td valign="top">You made the light work for  you and caught a warm moment in what could be a very boring environment.  Well done.</td>', 'You made the light work for  you and caught a warm moment in what could be a very boring environment.  Well done.', '2006-05-15 21:54:43.000000', NULL, 1),
(2418903, 332764, 42984, '<td valign="top">Hey really good mono treatment.  I like the PP as it has resulted in not just a picture of a guy on a rope but of a mood.  It has feeling, not just ''stuff''.</td>', 'Hey really good mono treatment.  I like the PP as it has resulted in not just a picture of a guy on a rope but of a mood.  It has feeling, not just ''stuff''.', '2006-05-15 21:55:06.000000', NULL, 1),
(2418907, 333757, 42984, '<td valign="top">I really like this image.  I''m still undecided about how relevant it is as an enviromental portrait but at the moment, it feels ok.</td>', 'I really like this image.  I''m still undecided about how relevant it is as an enviromental portrait but at the moment, it feels ok.', '2006-05-15 21:55:59.000000', NULL, 1),
(2418908, 334358, 51125, '<td valign="top">Strong light and wonderful sense of moment.</td>', 'Strong light and wonderful sense of moment.', '2006-05-15 21:56:06.000000', NULL, 1),
(2418914, 333821, 55642, '<td valign="top">Is he really that sunburnt, or did something happen in PP?</td>', 'Is he really that sunburnt, or did something happen in PP?', '2006-05-15 21:58:07.000000', NULL, 1),
(2418916, 333915, 51125, '<td valign="top">Really great composition and concept.  If you dodged the sky a bit this would be a ten in my book.</td>', 'Really great composition and concept.  If you dodged the sky a bit this would be a ten in my book.', '2006-05-15 21:58:25.000000', NULL, 1),
(2418917, 334571, 51125, '<td valign="top">Great light and concept</td>', 'Great light and concept', '2006-05-15 21:58:58.000000', NULL, 1),
(2418962, 332599, 48560, '<td valign="top">you must be getting a beating from the voters for DNMC, no? Things like, where is the "potrait"? Clearly they were expecting a human face... Narrow minded, I guess. I dont see anywhere in the challenge description that says we must shoot a photo of people. I think this is a creative out-of-the-box idea. Not so sure I liked the slight tilt though.</td>', 'you must be getting a beating from the voters for DNMC, no? Things like, where is the "potrait"? Clearly they were expecting a human face... Narrow minded, I guess. I dont see anywhere in the challenge description that says we must shoot a photo of people. I think this is a creative out-of-the-box idea. Not so sure I liked the slight tilt though.', '2006-05-15 22:20:28.000000', NULL, 1),
(2418965, 333801, 11800, '<td valign="top">I like how he almost fills the frame but there is enough background to see this is taken in a large city. Nice.</td>', 'I like how he almost fills the frame but there is enough background to see this is taken in a large city. Nice.', '2006-05-15 22:21:16.000000', NULL, 1),
(2418979, 334562, 11800, '<td valign="top">Good portrait. Almost enough background is showing to think it''s a barn, and this would be a great ad, but I''d like see more of his surroundings.</td>', 'Good portrait. Almost enough background is showing to think it''s a barn, and this would be a great ad, but I''d like see more of his surroundings.', '2006-05-15 22:25:00.000000', NULL, 1),
(2418984, 334313, 25397, '<td valign="top">The sense of movement in his hands makes the picture<br/>Great work</td>', 'The sense of movement in his hands makes the pictureGreat work', '2006-05-15 22:26:14.000000', NULL, 1),
(2418991, 333663, 25397, '<td valign="top">outstanding character study</td>', 'outstanding character study', '2006-05-15 22:28:17.000000', NULL, 1),
(2418993, 334545, 37730, '<td valign="top">Great photo.</td>', 'Great photo.', '2006-05-15 22:28:54.000000', NULL, 1),
(2418994, 334568, 38496, '<td valign="top">A bit more of the campus would have made this more of an environmental shot, instead of just a picture of a graduate.  Nice portrait, though.</td>', 'A bit more of the campus would have made this more of an environmental shot, instead of just a picture of a graduate.  Nice portrait, though.', '2006-05-15 22:28:55.000000', NULL, 1),
(2418998, 334586, 38496, '<td valign="top">Nice.  I like the close up of the face, while still showing the greenhouse and plants.</td>', 'Nice.  I like the close up of the face, while still showing the greenhouse and plants.', '2006-05-15 22:29:52.000000', NULL, 1),
(2418999, 334438, 38496, '<td valign="top">I''m not a big fan of the b/w effect here (to dark and gloomy), but the portrait is nice.</td>', 'I''m not a big fan of the b/w effect here (to dark and gloomy), but the portrait is nice.', '2006-05-15 22:30:38.000000', NULL, 1),
(2419000, 334213, 37730, '<td valign="top">Now there''s a job!  Might be dangerous though.  Errant shots and all.  Nice photo.</td>', 'Now there''s a job!  Might be dangerous though.  Errant shots and all.  Nice photo.', '2006-05-15 22:30:44.000000', NULL, 1),
(2419004, 334571, 37730, '<td valign="top">Very cool idea.  Well done.</td>', 'Very cool idea.  Well done.', '2006-05-15 22:31:18.000000', NULL, 1),
(2419005, 334524, 38496, '<td valign="top">The face is a little blurry and the ligting is a little harsh, otherwise this is a really nice shot.</td>', 'The face is a little blurry and the ligting is a little harsh, otherwise this is a really nice shot.', '2006-05-15 22:31:54.000000', NULL, 1),
(2419008, 334579, 38496, '<td valign="top">The tilt makes me feel a little dizzy, which might well be the effect you were going for?</td>', 'The tilt makes me feel a little dizzy, which might well be the effect you were going for?', '2006-05-15 22:32:35.000000', NULL, 1),
(2419009, 334008, 38496, '<td valign="top">Very nice.  I like the contrast of the jacket with the blues of the water.</td>', 'Very nice.  I like the contrast of the jacket with the blues of the water.', '2006-05-15 22:33:20.000000', NULL, 1),
(2419012, 333975, 38496, '<td valign="top">Beautiful shot.  I really like the blurry background.</td>', 'Beautiful shot.  I really like the blurry background.', '2006-05-15 22:34:28.000000', NULL, 1),
(2419013, 333372, 38496, '<td valign="top">beautiful pet protrait.</td>', 'beautiful pet protrait.', '2006-05-15 22:34:52.000000', NULL, 1),
(2419014, 332721, 25397, '<td valign="top">awesome location, I''d love to go check that out myself. :-)</td>', 'awesome location, I''d love to go check that out myself. :-)', '2006-05-15 22:35:55.000000', NULL, 1),
