(2419017, 333552, 38496, '<td valign="top">I''m not really sure a ladybug qualifies as a portrait in my book.  Nice macro shot, though.</td>', 'I''m not really sure a ladybug qualifies as a portrait in my book.  Nice macro shot, though.', '2006-05-15 22:36:48.000000', NULL, 1),
(2419019, 332574, 38496, '<td valign="top">I''d like to see more of the subjects face.</td>', 'I''d like to see more of the subjects face.', '2006-05-15 22:37:20.000000', NULL, 1),
(2419023, 333890, 38496, '<td valign="top">It would be nice to see more of the firefighter for a portrait.  This is a nice shot, but not sure it''s really a portrait.</td>', 'It would be nice to see more of the firefighter for a portrait.  This is a nice shot, but not sure it''s really a portrait.', '2006-05-15 22:38:00.000000', NULL, 1),
(2419025, 334125, 38496, '<td valign="top">Would like to see more of the subject, given that it''s a portrait.</td>', 'Would like to see more of the subject, given that it''s a portrait.', '2006-05-15 22:38:38.000000', NULL, 1),
(2419031, 333770, 38496, '<td valign="top">not reallya portrait...</td>', 'not reallya portrait...', '2006-05-15 22:40:27.000000', NULL, 1),
(2419037, 334102, 38496, '<td valign="top">gross... shudder... been there too many times.  Cute kid, though, and nice portrait.</td>', 'gross... shudder... been there too many times.  Cute kid, though, and nice portrait.', '2006-05-15 22:41:32.000000', NULL, 1),
(2419039, 333473, 38496, '<td valign="top">cute shot, but the harsh shadows are a little distracting, and make it look like a snapshot.</td>', 'cute shot, but the harsh shadows are a little distracting, and make it look like a snapshot.', '2006-05-15 22:42:19.000000', NULL, 1),
(2419043, 334550, 38496, '<td valign="top">beautiful portrait!</td>', 'beautiful portrait!', '2006-05-15 22:43:06.000000', NULL, 1),
(2419045, 333417, 38496, '<td valign="top">Would have liked to see a little more of the welding shop, but at least the helmut (whatever you call his headwear) gives me an idea what he''s doing/who he is.</td>', 'Would have liked to see a little more of the welding shop, but at least the helmut (whatever you call his headwear) gives me an idea what he''s doing/who he is.', '2006-05-15 22:44:11.000000', NULL, 1),
(2419047, 333575, 38496, '<td valign="top">Nice enough portrait, but I don''t really get a sense of what the environment is.</td>', 'Nice enough portrait, but I don''t really get a sense of what the environment is.', '2006-05-15 22:44:44.000000', NULL, 1),
(2419055, 333035, 38496, '<td valign="top">Finally!   A portrait of someone in their environment!  Very nice.  The sparkly curtain thing in the background is a little distracting.   I like the way his drawing board is lit, though, and draws the eye.</td>', 'Finally!   A portrait of someone in their environment!  Very nice.  The sparkly curtain thing in the background is a little distracting.   I like the way his drawing board is lit, though, and draws the eye.', '2006-05-15 22:46:50.000000', NULL, 1),
(2419059, 334295, 38496, '<td valign="top">Nice idea, and has emotional impact due to the subject.  I don''t particularly care for the bandaid in color.  Also the blanket (?) in the background is distracting.</td>', 'Nice idea, and has emotional impact due to the subject.  I don''t particularly care for the bandaid in color.  Also the blanket (?) in the background is distracting.', '2006-05-15 22:48:32.000000', NULL, 1),
(2419062, 332599, 38496, '<td valign="top">Um.. where''s the person?  Fell off the bike, maybe?  Not really a portrait, although the sun over the water is beautiful.</td>', 'Um.. where''s the person?  Fell off the bike, maybe?  Not really a portrait, although the sun over the water is beautiful.', '2006-05-15 22:49:09.000000', NULL, 1),
(2419066, 334493, 38496, '<td valign="top">Nice portrait.  A little grainy, and I''d like it better if the bottoms of his feet weren''t cut off.  Very cute expression and nice composition.</td>', 'Nice portrait.  A little grainy, and I''d like it better if the bottoms of his feet weren''t cut off.  Very cute expression and nice composition.', '2006-05-15 22:50:18.000000', NULL, 1),
(2419069, 333655, 38496, '<td valign="top">Um.. where''s the person?  Is this a portrait of a boat?  Or of the seagulls?  The water is pretty...</td>', 'Um.. where''s the person?  Is this a portrait of a boat?  Or of the seagulls?  The water is pretty...', '2006-05-15 22:51:13.000000', NULL, 1),
(2419070, 332681, 38496, '<td valign="top">Absolutely beautiful shot.  But not really a portrait in my mind.  It''s hard to see the subject.</td>', 'Absolutely beautiful shot.  But not really a portrait in my mind.  It''s hard to see the subject.', '2006-05-15 22:52:10.000000', NULL, 1),
(2419072, 334499, 38496, '<td valign="top">Nice macro... not really a portrait though.</td>', 'Nice macro... not really a portrait though.', '2006-05-15 22:52:37.000000', NULL, 1),
(2419075, 334504, 51125, '<td valign="top">Wonderful composition, I love the lines and power of the gaze.  I would bring it down a stop or two.</td>', 'Wonderful composition, I love the lines and power of the gaze.  I would bring it down a stop or two.', '2006-05-15 22:54:03.000000', NULL, 1),
(2419079, 333922, 51125, '<td valign="top">Great light and composition but I think to be a true environmental composition it should have at least a hint of another musician or background.</td>', 'Great light and composition but I think to be a true environmental composition it should have at least a hint of another musician or background.', '2006-05-15 22:55:25.000000', NULL, 1),
(2419080, 332250, 38496, '<td valign="top">One of my favorites!  I love the motion of the children while the teacher sits still and calm.  very nice shot.</td>', 'One of my favorites!  I love the motion of the children while the teacher sits still and calm.  very nice shot.', '2006-05-15 22:55:47.000000', NULL, 1),
(2419083, 334572, 51125, '<td valign="top">Outstanding sense of moment, focus and the soft light is working for you.</td>', 'Outstanding sense of moment, focus and the soft light is working for you.', '2006-05-15 22:57:45.000000', NULL, 1),
(2419085, 334060, 51125, '<td valign="top">I really like the processing here.  It add a powerful sense of mystery.</td>', 'I really like the processing here.  It add a powerful sense of mystery.', '2006-05-15 22:59:23.000000', NULL, 1),
(2419088, 334236, 36006, '<td valign="top">I thought you were taller, Beagleboy. Nice job anyway. No, no, no, don''t expect any long, bloated, critique. You just get a ''nice job''.</td>', 'I thought you were taller, Beagleboy. Nice job anyway. No, no, no, don''t expect any long, bloated, critique. You just get a ''nice job''.', '2006-05-15 22:59:51.000000', NULL, 1),
(2419089, 333735, 51125, '<td valign="top">The processing works well.</td>', 'The processing works well.', '2006-05-15 22:59:52.000000', NULL, 1),
(2419090, 334108, 38496, '<td valign="top">nice portrait of a ball, but it would have had more impact with a player sitting next to it...</td>', 'nice portrait of a ball, but it would have had more impact with a player sitting next to it...', '2006-05-15 23:00:20.000000', NULL, 1),
(2419091, 334491, 38496, '<td valign="top">dnmc</td>', 'dnmc', '2006-05-15 23:00:44.000000', NULL, 1),
