(2419229, 334589, 37524, '<td valign="top">Crazy shot.  Weren''t you afraid of losing your camera?</td>', 'Crazy shot.  Weren''t you afraid of losing your camera?', '2006-05-16 00:06:01.000000', NULL, 1),
