(2424383, 333903, 23430, '<td valign="top">Love the shallow DOF and the pastel background colours with the sharp contrasting colours of the bird. The size and placement of the bird is excellent.</td>', 'Love the shallow DOF and the pastel background colours with the sharp contrasting colours of the bird. The size and placement of the bird is excellent.', '2006-05-17 09:29:40.000000', NULL, 1),
(2424388, 332300, 75713, '<td valign="top">sure meets the challenge - a woman''s work is never done... :)</td>', 'sure meets the challenge - a woman''s work is never done... :)', '2006-05-17 09:30:54.000000', NULL, 1),
(2424399, 334449, 75713, '<td valign="top">nice, getting them all ''singing'' at the same time.</td>', 'nice, getting them all ''singing'' at the same time.', '2006-05-17 09:33:31.000000', NULL, 1),
(2424400, 333473, 23430, '<td valign="top">Very cute. It looks like your models were having as much fun as you. The light at the front is nice but it would have been good if you could have reduced the shadows on the wall too.</td>', 'Very cute. It looks like your models were having as much fun as you. The light at the front is nice but it would have been good if you could have reduced the shadows on the wall too.', '2006-05-17 09:33:37.000000', NULL, 1),
(2424407, 334488, 75713, '<td valign="top">fantastic shot in every way</td>', 'fantastic shot in every way', '2006-05-17 09:35:05.000000', NULL, 1),
