(2424419, 332574, 23430, '<td valign="top">This shot has a good feel to it. The colours, composition, the action and the bright spot in the middle, it''s all good.</td>', 'This shot has a good feel to it. The colours, composition, the action and the bright spot in the middle, it''s all good.', '2006-05-17 09:39:02.000000', NULL, 1),
(2424449, 334520, 12733, '<td valign="top">A very well lit and posed portrait. But as an environmental, I think it would work better to back off the subject and get in more of the antiques.</td>', 'A very well lit and posed portrait. But as an environmental, I think it would work better to back off the subject and get in more of the antiques.', '2006-05-17 09:45:41.000000', NULL, 1),
(2424453, 332133, 23430, '<td valign="top">A bit of a stretch to call this a portrait though technically it may be. Still it''s a very nice scene with all that negative space. The nice bright circle of the sun and the parachutist looks great. The hills look good too and the cloud is probably not needed but doesn''t take anything away either.</td>', 'A bit of a stretch to call this a portrait though technically it may be. Still it''s a very nice scene with all that negative space. The nice bright circle of the sun and the parachutist looks great. The hills look good too and the cloud is probably not needed but doesn''t take anything away either.', '2006-05-17 09:46:30.000000', NULL, 1),
(2424456, 333948, 12733, '<td valign="top">Very humorous photo - I''d like to see more humor on this site.</td>', 'Very humorous photo - I''d like to see more humor on this site.', '2006-05-17 09:47:56.000000', NULL, 1),
(2424460, 334013, 23430, '<td valign="top">I like the composition and the colours against the dark background in this one.</td>', 'I like the composition and the colours against the dark background in this one.', '2006-05-17 09:48:47.000000', NULL, 1),
(2424468, 333473, 12733, '<td valign="top">A cute shot, but that heavy shadow and tilted table make me rate it lower.</td>', 'A cute shot, but that heavy shadow and tilted table make me rate it lower.', '2006-05-17 09:50:34.000000', NULL, 1),
(2424473, 334567, 12733, '<td valign="top">Nice balance of subject to background.</td>', 'Nice balance of subject to background.', '2006-05-17 09:51:32.000000', NULL, 1),
