(2437363, 332599, 43565, '<td valign="top">IMO, a portrait should include a person (or perhaps an animal).  As for the shot, I wish more of the bike was included.</td>', 'IMO, a portrait should include a person (or perhaps an animal).  As for the shot, I wish more of the bike was included.', '2006-05-19 18:40:21.000000', NULL, 1),
(2437364, 333531, 43565, '<td valign="top">Not what I think of when I am told a portrait.  I would like it better if the focus was sharper.</td>', 'Not what I think of when I am told a portrait.  I would like it better if the focus was sharper.', '2006-05-19 18:40:27.000000', NULL, 1),
(2437368, 332949, 43565, '<td valign="top">This is not a portrait IMO.</td>', 'This is not a portrait IMO.', '2006-05-19 18:41:23.000000', NULL, 1),
