INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2447086, 334457, 36006, '<td valign="top">Your work is outstanding.<br/> <br/>It''s too bad this was not some sort of a landscape challenge, or a long shot challenge.<br/> <br/>The image is good. Please keep up the good work. Please try again.</td>', 'Your work is outstanding. It''s too bad this was not some sort of a landscape challenge, or a long shot challenge. The image is good. Please keep up the good work. Please try again.', '2006-05-22 17:32:29.000000', NULL, 0),
(2447092, 333679, 36006, '<td valign="top">In the future, as a photographer, you must have forthought to what you are trying to sell the viewer.<br/> <br/>Just like dating, first impressions are everything. Next, you have to convince the viewer to take a second look.<br/> <br/>Convinceing the viewer is everything, else the image is lost.<br/> <br/>In this image, a surf board, or wave board, or boogie board, hell, even a swim suit would of faired better than nothing. Think props.<br/> <br/>Don''t give up.</td>', 'In the future, as a photographer, you must have forthought to what you are trying to sell the viewer. Just like dating, first impressions are everything. Next, you have to convince the viewer to take a second look. Convinceing the viewer is everything, else the image is lost. In this image, a surf board, or wave board, or boogie board, hell, even a swim suit would of faired better than nothing. Think props. Don''t give up.', '2006-05-22 17:39:10.000000', NULL, 0),
(2447097, 334214, 36006, '<td valign="top">You do good work from what I have seen.<br/> <br/>This image would of done so much better with a little more forethought on your part.<br/> <br/>As a viewer, I must be convinced of your intentions or all is to waste.<br/> <br/>Good luck in the future.</td>', 'You do good work from what I have seen. This image would of done so much better with a little more forethought on your part. As a viewer, I must be convinced of your intentions or all is to waste. Good luck in the future.', '2006-05-22 17:42:39.000000', NULL, 0),
(2447099, 333819, 50389, '<td valign="top">I thought this was worth far more than it placed. I like it a lot - you woz robbed!</td>', 'I thought this was worth far more than it placed. I like it a lot - you woz robbed!', '2006-05-22 17:43:37.000000', NULL, 0),
(2447109, 333705, 50389, '<td valign="top">I rated this as one of the best in the challenge. Does a portraite have to be lloking at the camera? I am not so sure - this seems to have counted against you. Anyway a great picture in my book. Well done.</td>', 'I rated this as one of the best in the challenge. Does a portraite have to be lloking at the camera? I am not so sure - this seems to have counted against you. Anyway a great picture in my book. Well done.', '2006-05-22 17:47:23.000000', NULL, 0),
(2447122, 334212, 50389, '<td valign="top">This was my number 1. I am stunned that it didn''t do better. Great shot and a definite fit to the challenge. <br/> <br/>Hard luck with the voting but great picture</td>', 'This was my number 1. I am stunned that it didn''t do better. Great shot and a definite fit to the challenge.  Hard luck with the voting but great picture', '2006-05-22 17:56:07.000000', NULL, 0),
