(2592463, 333647, 27133, '<td valign="top">Awesome!</td>', 'Awesome!', '2006-07-06 08:53:41.000000', NULL, 0),
(2597235, 332250, 60862, '<td valign="top">This is one of my favorites, and one of my faves among my faves.<br/> <br/>My wife was also a teacher, and you''ve so captured her life.  As I''m sure you know, it goes WAAAYYYY beyond the classroom, too!</td>', 'This is one of my favorites, and one of my faves among my faves. My wife was also a teacher, and you''ve so captured her life.  As I''m sure you know, it goes WAAAYYYY beyond the classroom, too!', '2006-07-07 12:32:47.000000', NULL, 0),
(2601647, 334162, 14986, '<td valign="top">I think this is an awesome photo!  Great perspective and color.  Nothing really fancy about it, but a good eye for how to take the shot and the editing adds to the interest.</td>', 'I think this is an awesome photo!  Great perspective and color.  Nothing really fancy about it, but a good eye for how to take the shot and the editing adds to the interest.', '2006-07-08 21:57:14.000000', NULL, 0),
