(2627464, 333594, 25464, '<td valign="top">This is a great shot.  Would make a great stock shot.  I would try taking this same shot with the yellow lines beginning in the lower right corner and placing the subject more on the upper rule of thirds area.  This would show a bit more of the road ahead as well.  It might be even stronger.  Great the way it is though.</td>', 'This is a great shot.  Would make a great stock shot.  I would try taking this same shot with the yellow lines beginning in the lower right corner and placing the subject more on the upper rule of thirds area.  This would show a bit more of the road ahead as well.  It might be even stronger.  Great the way it is though.', '2006-07-16 18:33:04.000000', NULL, 0),
(2647106, 332300, 5885, '<td valign="top">There is noooo way the woman in this photo is 42. I''m calling for a DQ :-)</td>', 'There is noooo way the woman in this photo is 42. I''m calling for a DQ :-)', '2006-07-21 19:16:36.000000', NULL, 0),
